import type { Metadata } from "next";
import { site } from "@/content/site";

/** Social sharing card generated by app/og.png/route.tsx. */
export const OG_IMAGE = { url: "/og.png", width: 1200, height: 630, alt: `${site.name}: ${site.tagline}`, type: "image/png" };

/**
 * Page metadata with a complete Open Graph block. Next.js replaces (rather
 * than merges) a parent's `openGraph`, so every page sets all fields.
 */
export function pageMetadata({ title, description, path, noIndex = false }: { title: string; description: string; path: string; noIndex?: boolean }): Metadata {
  const fullTitle = `${title} · ${site.name}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { type: "website", siteName: site.name, locale: "en_US", title: fullTitle, description, url: path, images: [OG_IMAGE] },
    twitter: { card: "summary_large_image", title: fullTitle, description, images: [OG_IMAGE.url] },
    ...(noIndex ? { robots: { index: false, follow: true } } : {}),
  };
}
